			JSON: spec.InternalServerError{},
		}
	}
	if !resp.Exists {
		if protocol != "" {
			return util.JSONResponse{
				Code: http.StatusNotFound,
				JSON: spec.NotFound("The protocol is unknown."),
			}
		}
		return util.JSONResponse{
			Code: http.StatusOK,
			JSON: struct{}{},
		}
	}
	if protocol != "" {
		return util.JSONResponse{
			Code: http.StatusOK,
			JSON: resp.Protocols[protocol],
		}
	}
	return util.JSONResponse{
		Code: http.StatusOK,
		JSON: resp.Protocols,
	}
}

